local Time = CS.UnityEngine.Time
local Text = CS.UnityEngine.UI.Text
local Image = CS.UnityEngine.UI.Image
local Animation = CS.UnityEngine.Animation
local Animator = CS.UnityEngine.Animator
local Collider = CS.UnityEngine.Collider
local SphereCollider = CS.UnityEngine.SphereCollider
local Mathf = CS.UnityEngine.Mathf

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local LuaParameters = CS.Engine.Modules.LuaParameters



-- ========================================================




-- ========================================================

function PipelineVCamApproach:__init()
    self.controller = nil
    self._controller = nil -- PipelineVCamController
end


function PipelineVCamApproach:__delete()
end


function PipelineVCamApproach:Awake()
    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 OnTriggerEnter() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end

        behaviourAction.OnTriggerExitAction = function(behaviourAction,other_)
            self:OnTriggerExit(other_)
        end
    end

    -- ====================
    self.transform = self.controller.gameObject.transform
    self.sphereCollider = KTool.GetOrAddComponent(self.controller.gameObject, typeof(SphereCollider))
    assert( self.sphereCollider )


end


function PipelineVCamApproach:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function PipelineVCamApproach:SetController( controller_ )
    self._controller = controller_
end

---@return void
---@param other_ UnityEngine.Collider
function PipelineVCamApproach:OnTriggerEnter(other_)
    self._controller:InApproach( other_.gameObject, self.transform.position, self:GetColliderRadius() )
end


---@return void
---@param other_ UnityEngine.Collider
function PipelineVCamApproach:OnTriggerExit(other_)
    self._controller:OutApproach( other_.gameObject )
end




function PipelineVCamApproach:GetColliderRadius()
    local lScale = self.transform.localScale
    local localScaleVal = Mathf.Max( Mathf.Max(lScale.x, lScale.y), lScale.z )
    return localScaleVal * self.sphereCollider.radius
end 



return PipelineVCamApproach

